import {prepare,probabilities} from './quantum.js';
import {acquire} from './studio-model.js';
import {StereoRenderer,audioConfig,referenceToneData,wavHeader,pcm16} from './studio-audio.js';
import {renderMusicBuffer} from './music-export.js';
export async function renderTake(take,format='wav',{signal,progress=()=>{}}={}){if(!['wav','mp3'].includes(format))throw Error('Unsupported format');const prepared=[];let total=0;
 for(const t of take.segments||[take]){if(signal?.aborted)throw new DOMException('Cancelled','AbortError');if(t.bench==='music'){const c=t.config.probs?t.config:{...t.config,probs:probabilities(prepare(t.config),t.config.basis0,t.config.basis1)},r=await renderMusicBuffer(c,t.sequence,{variant:t.variant||'processed',signal,preview:t.sequence.length===1});prepared.push({channels:r.channels,frames:r.plan.frames});total+=r.plan.frames;}
 else {const c=t.config,highest=Math.max(1,...c.qubits.map(q=>Math.abs(q.nu)+c.j/2));let samples=2048;while(samples<8*highest*c.windowMs/1000&&samples<65536)samples*=2;const d=t.reference?referenceToneData():await acquire(c,{samples:t.samples||samples});if(!t.reference&&Math.max(...d.frequencies.map(Math.abs))>=1/(2*d.dt))throw Error('Acquisition exceeds its Nyquist limit. Shorten the window or reduce J/offsets.');const renderer=new StereoRenderer(d,audioConfig(c));prepared.push({renderer,frames:renderer.frames});total+=renderer.frames;}}
 const gap=Math.round(.15*44100);total+=gap*(prepared.length-1);const encoder=format==='mp3'?new globalThis.lamejs.Mp3Encoder(2,44100,128):null,chunks=encoder?[]:[wavHeader(total)];let done=0,ticks=0;
 const append=async channels=>{if(signal?.aborted)throw new DOMException('Cancelled','AbortError');const pcm=pcm16(channels);if(encoder){const b=encoder.encodeBuffer(pcm.left,pcm.right);if(b.length)chunks.push(new Uint8Array(b));}else{const b=new ArrayBuffer(pcm.interleaved.length*2),v=new DataView(b);for(let i=0;i<pcm.interleaved.length;i++)v.setInt16(i*2,pcm.interleaved[i],true);chunks.push(b);}done+=channels[0].length;if(++ticks%30===0){progress(done/total);await new Promise(r=>setTimeout(r,0));}};
 for(let i=0;i<prepared.length;i++){const p=prepared[i],size=encoder?1152:8192;for(let at=0;at<p.frames;at+=size){const n=Math.min(size,p.frames-at);await append(p.renderer?p.renderer.next(n):p.channels.map(c=>c.subarray(at,at+n)));}if(i<prepared.length-1)for(let at=0;at<gap;at+=size)await append([new Float32Array(Math.min(size,gap-at)),new Float32Array(Math.min(size,gap-at))]);}
 if(encoder){const b=encoder.flush();if(b.length)chunks.push(new Uint8Array(b));}progress(1);return {blob:new Blob(chunks,{type:encoder?'audio/mpeg':'audio/wav'}),frames:total,duration:total/44100};}
